import{_ as t,o as s,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-23（衰老 / 代谢 / 蛋白稳态）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-23-biomed.md","filePath":"topics/biomedicine/science-daily-2026-10-23-biomed.md"}'),e={name:"topics/biomedicine/science-daily-2026-10-23-biomed.md"};function i(g,o,c,d,l,a){return s(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="科学日报-·-2026-10-23-衰老-代谢-蛋白稳态" tabindex="-1">科学日报 · 2026-10-23（衰老 / 代谢 / 蛋白稳态） <a class="header-anchor" href="#科学日报-·-2026-10-23-衰老-代谢-蛋白稳态" aria-label="Permalink to &quot;科学日报 · 2026-10-23（衰老 / 代谢 / 蛋白稳态）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-23.md</code> — 第42期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（延续 10-21 起的确立做法）。</p></blockquote><hr><h2 id="科学日报-2026-10-23-低温延寿的分子路线——一条可「搬运和补充」的-bh2-代谢通路" tabindex="-1">科学日报 2026-10-23：低温延寿的分子路线——一条可「搬运和补充」的 BH2 代谢通路 <a class="header-anchor" href="#科学日报-2026-10-23-低温延寿的分子路线——一条可「搬运和补充」的-bh2-代谢通路" aria-label="Permalink to &quot;科学日报 2026-10-23：低温延寿的分子路线——一条可「搬运和补充」的 BH2 代谢通路&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-23.md</code> ｜ DOI: 10.1038/s41586-026-11152-9</p></blockquote><ul><li>背景：<strong>适度低温</strong>能跨物种<strong>延长寿命、促进健康</strong>，但<strong>分子机制长期不清</strong>（此前基本停留在「现象确凿、通路空白」）。</li><li>本条定义的系统（代谢物驱动的<strong>多组织信号系统</strong>，在秀丽隐杆线虫中）： <ul><li>低温<strong>上调生物蝶呤合成酶 CAT-4</strong>（人源同源为 <strong>GCH1</strong>）→ 提高<strong>二氢生物蝶呤 BH2</strong> 产量；</li><li><strong>BH2 是可运输的储库</strong>，负责把活性辅因子 <strong>BH4（四氢生物蝶呤）</strong> 运出去：<strong>在肌肉产生 → 运输到远端组织</strong>（肠道、神经元）→ 由<strong>补救酶 DHFR-1</strong> 转成 <strong>BH4</strong>；</li><li><strong>BH4 是苯丙氨酸羟化酶 PAH-1 的必需辅因子</strong> → 促进<strong>酪氨酸合成</strong> → <strong>延长寿命</strong>；这条 BH2–BH4 轴同时<strong>防止与疾病相关的蛋白聚集</strong>及随后的<strong>神经元功能障碍</strong>。</li></ul></li><li><strong>关键实验（因果性，而非相关性）</strong>：<strong>只在肌肉中提高 BH2 合成</strong>，就足以在<strong>常温甚至升高温度</strong>下<strong>延寿</strong>，并<strong>在远端组织抑制病理性聚集</strong> → 冷不是必需的，<strong>把中间代谢物补上就够</strong>。</li><li><strong>跨物种外推（人细胞）</strong>：补充 <strong>BH2 或酪氨酸</strong>可减少<strong>亨廷顿病</strong>相关的 <strong>polyQ 扩展蛋白</strong>、以及导致 <strong>ALS</strong> 的 <strong>TDP-43 与 FUS 突变体</strong>的聚集。</li><li>结论：<strong>BH2 是被冷诱导出来的代谢物</strong> —— 它的「<strong>合成 + 跨组织运输 + 转成活性 BH4</strong>」三步，即可<strong>保持全身蛋白稳态并延长寿命</strong>。</li><li>洞察（对本库 <code>biomedicine</code>）：这条的价值不在「低温有益」（早就知道），而在<strong>把一句环境条件翻译成一条可搬运、可外源补充的分子轴</strong>。迁移成两条可复用判据：① <strong>「多组织效应」往往有一个专职的运输中间体</strong>（BH2 在此扮演的角色，类似库内 10-12「肠道菌经十五烷酸影响肝脏」的短链脂肪酸中介）；② <strong>干预的最小充分条件常落在「生产端的一个组织」而非全身</strong>（只改肌肉即全身受益）→ 对任何「环境暴露 → 全身表型」的结论，先找<strong>那个可运输的中间物</strong>与<strong>那个最小充分的生产位点</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第42期 科学板块</p></blockquote><p>关键词：低温延寿、冷诱导代谢物、生物蝶呤、BH2、二氢生物蝶呤、BH4、四氢生物蝶呤、CAT-4、GCH1、DHFR-1、PAH-1、酪氨酸合成、蛋白稳态、proteostasis、polyQ、亨廷顿病、TDP-43、FUS、ALS、跨组织运输中间体、最小充分的干预位点、肌肉到远端组织</p><p>关联：<code>topics/biomedicine/science-daily-2026-10-20.md</code>（Hes1 频率编码）、<code>topics/biomedicine/2026-q3-breakthroughs.md</code>（衰老：百岁老人/DEAF1/MTCH2）、<code>topics/biomedicine/science-daily-2026-10-12.md</code>（肠道菌—十五烷酸—肝脏）、<code>topics/biomedicine/index.md</code></p>',10)])])}const b=t(e,[["render",i]]);export{p as __pageData,b as default};
